async function persistSelectedPlan(body){
  const planCode = String(body?.plan_code || '').trim().toLowerCase()
  if(!planCode) return
  const plan = typeof getPlanPreset === 'function' ? getPlanPreset(planCode) : null
  await originalFetchJson(API + '/subscription/checkout', {
    method:'POST',
    headers:{ 'Content-Type':'application/json' },
    body: JSON.stringify({
      plan_code: planCode,
      plan_name: plan?.name || '',
      accepted_terms: true,
      source: 'assinatura-ui-stripe'
    })
  })
}

http.fetchJson = function(url, options){
  const method = String(options?.method || 'GET').toUpperCase()
  const isCheckout = method === 'POST' && /\/api\/subscription\/stripe\/create-checkout(?:\?|$)/.test(String(url || ''))
  if(!isCheckout) return originalFetchJson(url, options)

  let body = {}
  try { body = JSON.parse(String(options?.body || '{}')) || {} } catch (_) {}

  return persistSelectedPlan(body).then(() => originalFetchJson(url, {
    ...(options || {}),
    body: JSON.stringify({
      ...body,
      accepted_terms: true,
      accepted_privacy: true
    })
  }))
}

returnScript:
(function(){
      'use strict'

      const params = new URLSearchParams(window.location.search)
      const sessionId = String(params.get('session_id') || '').trim()
      const canceled = params.get('cancelado') === '1'
      const title = document.getElementById('title')
      const message = document.getElementById('message')
      const spinner = document.getElementById('spinner')
      const actions = document.getElementById('actions')

      function fail(text){
        spinner.style.display = 'none'
        title.textContent = 'Não foi possível confirmar a assinatura'
        message.textContent = text
        actions.classList.add('show')
      }

      if(canceled){
        spinner.style.display = 'none'
        title.textContent = 'Checkout cancelado'
        message.textContent = 'Nenhuma assinatura foi confirmada. Você pode voltar e tentar novamente quando quiser.'
        actions.classList.add('show')
        return
      }

      if(!sessionId.startsWith('cs_')){
        fail('O retorno da Stripe não trouxe uma sessão válida. Volte para Assinatura e tente novamente.')
        return
      }

      const http = window.ESTOFARIA_HTTP
      const auth = window.ESTOFARIA_AUTH
      if(!http || typeof http.fetchJson !== 'function' || !auth || typeof auth.getToken !== 'function'){
        fail('Não foi possível carregar a comunicação segura do aplicativo.')
        return
      }

      if(!auth.getToken()){
        window.location.replace('/login/')
        return
      }

      const API = (window.API_BASE || '') + '/api'
      http.fetchJson(API + '/subscription/stripe/confirm-checkout', {
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({session_id:sessionId}),
        cache:'no-store'
      }).then(function(out){
        if(!out || out.confirmed !== true){
          throw new Error('A Stripe ainda não confirmou a assinatura.')
        }
        title.textContent = 'Assinatura confirmada'
        message.textContent = 'Seu período gratuito foi confirmado. Abrindo o Estofaria Digital...'
        window.setTimeout(function(){
          window.location.replace('/painel/')
        }, 650)
      }).catch(function(err){
        console.error('[stripe-retorno] Falha ao confirmar checkout:', err)
        if(err && err.status === 401){
          window.location.replace('/login/')
          return
        }
        const detail = err && err.payload && err.payload.message
          ? err.payload.message
          : (err && err.message ? err.message : 'A confirmação não pôde ser concluída agora.')
        fail(detail)
      })
    })()
